"""Tracing helpers that degrade cleanly when OpenTelemetry is not installed."""
import logging
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Optional


trace_id_var: ContextVar[str] = ContextVar("trace_id", default="")  # ① 上下文变量
logger = logging.getLogger("evoagent")


class Observability:
    def __init__(self, service_name: str = "evoagent", endpoint: str = ""):
        self.tracer = None
        try:
            from opentelemetry import trace                          # ② 可选导入
            from opentelemetry.sdk.resources import Resource
            from opentelemetry.sdk.trace import TracerProvider
            from opentelemetry.sdk.trace.export import BatchSpanProcessor
            provider = TracerProvider(
                resource=Resource.create({"service.name": service_name})
            )
            if endpoint:
                from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
                provider.add_span_processor(
                    BatchSpanProcessor(OTLPSpanExporter(endpoint=endpoint))
                )
            trace.set_tracer_provider(provider)
            self.tracer = trace.get_tracer(service_name)
        except ImportError:
            self.tracer = None                                       # ③ 降级为 None

    @contextmanager
    def span(self, name: str, trace_id: str = "", **attributes):
        token = trace_id_var.set(trace_id or trace_id_var.get())     # ④ 设置 trace_id
        if self.tracer:
            with self.tracer.start_as_current_span(name) as span:
                for key, value in attributes.items():
                    if value is not None:
                        span.set_attribute(key, value)               # ⑤ 设置 span 属性
                try:
                    yield span
                except Exception as exc:
                    span.record_exception(exc)                       # ⑥ 记录异常
                    raise
                finally:
                    trace_id_var.reset(token)                        # ⑦ 恢复上下文
        else:
            try:
                yield None                                           # ⑧ 降级：返回 None
            finally:
                trace_id_var.reset(token)
